'use strict';
(() => {
  const button=document.getElementById('share-button'),config=window.DOMI_SUPABASE,editor=window.DomiEditor;
  if(!button||!config||!editor)return;
  const key='domi-schema-shares-v1',read=()=>{try{return JSON.parse(localStorage.getItem(key))||[];}catch{return[];}},write=value=>localStorage.setItem(key,JSON.stringify(value.slice(0,20)));
  const dialog=document.createElement('dialog');dialog.id='share-dialog';dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><div><span class="eyebrow">VISTA PÚBLICA</span><h2>Compartir schema</h2></div><button value="cancel" class="icon-button" aria-label="Cerrar">×</button></div><p class="share-copy">Crea una copia de solo lectura. Quien tenga la URL verá el esquema y las tarjetas del lienzo, incluidos sus dashboards, notas y extractos de fuentes. No tendrá acceso a tus proyectos ni a los documentos completos. Guarda la URL cuando se genere: por seguridad, el token no se conserva en el navegador.</p><label class="property"><span>Vigencia del enlace</span><select id="share-expiry"><option value="7">7 días</option><option value="30" selected>30 días</option><option value="never">Sin vencimiento</option></select></label><button id="share-create" type="button" class="primary full">Crear enlace público</button><div id="share-result" hidden><label class="property"><span>URL pública</span><input id="share-url" readonly></label><div class="dialog-row"><button id="share-copy" type="button" class="primary">Copiar URL</button><button id="share-open" type="button" class="outline">Abrir vista</button></div></div><p id="share-message" class="cloud-message" role="status"></p><div id="share-recent"></div></form>`;document.body.append(dialog);
  const $=id=>document.getElementById(id),message=(text,error=false)=>{$('share-message').textContent=text;$('share-message').classList.toggle('error',error);};
  async function call(body){const session=await window.DomiCloud?.getSession();if(!session)throw new Error('Inicia sesión desde el botón Nube para crear o revocar enlaces.');const response=await fetch(config.url+'/functions/v1/schema-share',{method:'POST',headers:{'Content-Type':'application/json','apikey':config.publishableKey,'Authorization':'Bearer '+session.access_token},body:JSON.stringify(body),signal:AbortSignal.timeout(30000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'No se pudo gestionar el enlace.');return data;}
  function publicUrl(token){return new URL('./share.html#'+token,location.href).href;}
  function renderRecent(){const values=read();$('share-recent').innerHTML=values.length?`<h3 class="share-subtitle">Enlaces creados en este navegador</h3>${values.map(x=>`<div class="share-row"><div><strong>${escapeHtml(x.title)}</strong><small>${x.expiresAt?'Vence '+new Date(x.expiresAt).toLocaleDateString('es-DO'):'Sin vencimiento'}</small></div><button type="button" class="quiet danger" data-revoke="${x.id}">Revocar</button></div>`).join('')}`:'';$('share-recent').querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await call({action:'revoke',id:b.dataset.revoke});write(read().filter(x=>x.id!==b.dataset.revoke));message('Enlace revocado.');renderRecent();}catch(error){message(error.message,true);b.disabled=false;}});}
  const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  button.onclick=()=>{$('share-result').hidden=true;message('');renderRecent();dialog.showModal();};
  $('share-create').onclick=async()=>{const create=$('share-create');create.disabled=true;message('Creando una copia segura…');try{const days=$('share-expiry').value==='never'?null:Number($('share-expiry').value),snapshot=window.SchemaModel.validate(editor.snapshot()),data=await call({action:'create',projectId:editor.projectId(),snapshot,expiresInDays:days}),url=publicUrl(data.token);$('share-url').value=url;$('share-result').hidden=false;const list=[{id:data.id,title:snapshot.title,expiresAt:data.expiresAt,createdAt:new Date().toISOString()},...read().filter(x=>x.id!==data.id)];write(list);renderRecent();message('Enlace listo. Puedes copiarlo o abrir la vista pública.');}catch(error){message(error.message,true);}finally{create.disabled=false;}};
  $('share-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('share-url').value);message('URL copiada.');}catch{$('share-url').select();document.execCommand('copy');message('URL copiada.');}};
  $('share-open').onclick=()=>window.open($('share-url').value,'_blank','noopener,noreferrer');
})();
